# Ford & Roach - Introductory Clinical Pharmacology (Wolters Kluwer).
# Chapter list: 12th edition, from the publisher's table of contents (shop.lww.com).
# Summaries cover each chapter's standard topics; they are written for this site, not copied from the book.

def ch(n, title, text, keys):
    return (n, title, [text], keys)

C = [
    ch(1, "General Principles of Pharmacology", "Drugs have chemical, generic, and brand (trade) names. The FDA approves drugs through phases of clinical trials; the DEA schedules controlled substances (I–V). Pharmacokinetics covers absorption, distribution, metabolism (mainly liver), and excretion (mainly kidneys). Pharmacodynamics is what the drug does to the body. Reactions include adverse reactions, allergies, tolerance, and drug interactions.", ["Generic vs. brand names", "Schedules I–V", "ADME", "Liver metabolizes, kidneys excrete"]),
    ch(2, "Administration of Drugs", "The rights of drug administration include right patient, drug, dose, route, time, and documentation. Routes include oral, sublingual, topical, inhalation, and parenteral (intradermal, subcutaneous, intramuscular, intravenous). IV gives the fastest effect.", ["Rights of administration", "Two patient identifiers", "IV fastest", "Parenteral routes"]),
    ch(3, "Making Drug Dosing Safer", "Medication errors are prevented with clear orders, avoiding dangerous abbreviations (e.g., 'U' for units), using leading zeros, double-checking high-alert drugs (insulin, heparin), barcode scanning, and reconciling medications at transitions.", ["Avoid error-prone abbreviations", "Leading zero", "High-alert drugs", "Medication reconciliation"]),
    ch(4, "The Nursing Process", "The nursing process—assessment, diagnosis, planning, implementation, evaluation—guides drug therapy: assess before giving, monitor for effects, and evaluate outcomes.", ["ADPIE", "Assess first", "Monitor effects", "Evaluate outcomes"]),
    ch(5, "Client and Family Teaching", "Teaching covers the drug's purpose, dose, timing, side effects, and what to report. Use plain language and teach-back. Adherence improves when patients understand their regimen.", ["Plain language", "Teach-back", "Report side effects", "Improve adherence"]),
    ch(6, "Antibacterial Drugs: Sulfonamides", "Sulfonamides (e.g., sulfamethoxazole-trimethoprim) are bacteriostatic and often used for UTIs. Encourage fluids to prevent crystals in urine. Watch for rash, including Stevens-Johnson syndrome, and photosensitivity.", ["Used for UTIs", "Bacteriostatic", "Push fluids", "Stevens-Johnson risk"]),
    ch(7, "Antibacterial Drugs That Disrupt the Bacterial Cell Wall", "Penicillins, cephalosporins, and carbapenems attack bacterial cell walls (bactericidal). Penicillin allergy is common and can cause anaphylaxis; there is some cross-sensitivity with cephalosporins. Vancomycin treats MRSA.", ["Penicillins and cephalosporins", "Check allergies", "Anaphylaxis risk", "Vancomycin for MRSA"]),
    ch(8, "Antibacterial Drugs That Interfere With Protein Synthesis", "Tetracyclines (avoid in children under 8 and pregnancy—stain teeth; avoid dairy and antacids), macrolides (erythromycin, azithromycin), aminoglycosides (gentamicin; ototoxic and nephrotoxic), and lincosamides (clindamycin; C. difficile risk).", ["Tetracycline stains teeth", "Aminoglycosides: ears and kidneys", "Macrolides", "Clindamycin → C. diff"]),
    ch(9, "Antibacterial Drugs That Interfere With DNA/RNA Synthesis", "Fluoroquinolones (ciprofloxacin, levofloxacin) can cause tendon rupture and photosensitivity. Metronidazole treats anaerobes and C. difficile; avoid alcohol (disulfiram-like reaction).", ["Fluoroquinolones: tendon rupture", "Metronidazole: no alcohol", "Photosensitivity", "Broad spectrum"]),
    ch(10, "Antitubercular Drugs", "TB is treated with multiple drugs for 6 months or more: isoniazid (liver toxicity, peripheral neuropathy—give vitamin B6), rifampin (turns body fluids red-orange), pyrazinamide, and ethambutol (vision changes). Adherence prevents resistance.", ["Multi-drug therapy", "Isoniazid: liver, B6", "Rifampin: orange fluids", "Ethambutol: vision"]),
    ch(11, "Antiviral Drugs", "Antivirals include acyclovir (herpes), oseltamivir (influenza; start within 48 hours), and antiretrovirals for HIV taken as combination therapy (ART). Antivirals don't cure most viral infections but control them.", ["Acyclovir for herpes", "Oseltamivir within 48 hours", "HIV combination therapy", "Control, not cure"]),
    ch(12, "Antifungal and Antiparasitic Drugs", "Antifungals include fluconazole, nystatin (oral thrush; swish and swallow), and amphotericin B (serious infections; kidney toxicity). Antiparasitic drugs treat worms, malaria, and lice.", ["Nystatin swish and swallow", "Amphotericin B: kidney toxicity", "Fluconazole", "Antimalarials"]),
    ch(13, "Nonopioid Analgesics: Salicylates and Nonsalicylates", "Aspirin (a salicylate) relieves pain, fever, and inflammation and prevents clots; avoid in children with viral illness (Reye's syndrome). Acetaminophen relieves pain and fever but not inflammation; overdose causes liver damage (antidote: acetylcysteine).", ["Aspirin: Reye's syndrome in kids", "Acetaminophen: liver toxicity", "Acetylcysteine antidote", "Aspirin prevents clots"]),
    ch(14, "Nonopioid Analgesics: NSAIDs and Migraine Headache Medications", "NSAIDs (ibuprofen, naproxen) relieve pain and inflammation but can cause GI bleeding and kidney problems; take with food. Triptans (sumatriptan) treat migraines but are avoided in heart disease.", ["NSAIDs: GI bleeding", "Take with food", "Triptans for migraine", "Avoid triptans with heart disease"]),
    ch(15, "Opioid Analgesics and Antagonists", "Opioids (morphine, hydrocodone, fentanyl) relieve severe pain. Main risk is respiratory depression—check respirations first. Other effects: constipation, sedation, nausea, dependence. Naloxone reverses opioids.", ["Respiratory depression", "Constipation", "Naloxone reverses", "Schedule II"]),
    ch(16, "Anesthetic Drugs", "Local anesthetics (lidocaine) block nerve conduction in an area; general anesthesia causes unconsciousness. Stages of anesthesia and preoperative drugs are covered. Monitor airway and vital signs after anesthesia.", ["Local vs. general", "Lidocaine", "Monitor airway", "Pre-op drugs"]),
    ch(17, "Central Nervous System Stimulants", "CNS stimulants (methylphenidate, amphetamines) treat ADHD and narcolepsy. Side effects include insomnia, appetite loss, and increased heart rate; give early in the day. They have abuse potential.", ["ADHD treatment", "Give in the morning", "Appetite loss", "Abuse potential"]),
    ch(18, "Antidementia Drugs", "Cholinesterase inhibitors (donepezil) and memantine slow symptoms of Alzheimer's disease but don't cure it. Side effects include nausea and dizziness.", ["Donepezil", "Memantine", "Slow, don't cure", "GI side effects"]),
    ch(19, "Antianxiety Drugs", "Benzodiazepines (lorazepam, alprazolam, diazepam) relieve anxiety but cause sedation and dependence; avoid alcohol. Flumazenil reverses benzodiazepines. Buspirone is a non-sedating alternative.", ["Benzodiazepines", "Sedation and dependence", "Flumazenil reverses", "No alcohol"]),
    ch(20, "Sedatives and Hypnotics", "Sedatives and hypnotics (zolpidem, some benzodiazepines) treat insomnia. Risks include next-day drowsiness, complex sleep behaviors, falls in older adults, and dependence. Use short-term.", ["Treat insomnia", "Fall risk", "Short-term use", "Avoid alcohol"]),
    ch(21, "Antidepressant Drugs", "Antidepressants include SSRIs (fluoxetine, sertraline), SNRIs, tricyclics, and MAOIs (avoid tyramine-rich foods like aged cheese—hypertensive crisis). They take 2–4 weeks to work. Watch for suicidal thoughts, especially in young people, and serotonin syndrome.", ["SSRIs first-line", "MAOIs: avoid tyramine", "2–4 weeks to work", "Suicide risk monitoring"]),
    ch(22, "Antipsychotic Drugs", "Antipsychotics treat schizophrenia and psychosis. First-generation drugs (haloperidol) can cause extrapyramidal symptoms and tardive dyskinesia; second-generation drugs (risperidone, olanzapine) cause weight gain and metabolic effects. Neuroleptic malignant syndrome is rare but dangerous. Lithium treats bipolar disorder (narrow therapeutic range).", ["Extrapyramidal effects", "Tardive dyskinesia", "Metabolic effects", "Lithium levels"]),
    ch(23, "Adrenergic Drugs", "Adrenergic (sympathomimetic) drugs mimic the sympathetic nervous system: epinephrine (anaphylaxis, cardiac arrest), norepinephrine, dopamine, and others raise blood pressure and heart rate. Monitor vital signs closely.", ["Mimic fight-or-flight", "Epinephrine for anaphylaxis", "Raise BP and HR", "Monitor closely"]),
    ch(24, "Adrenergic Blocking Drugs", "Beta blockers ('-olol': metoprolol, propranolol) lower heart rate and blood pressure; check pulse first and don't stop suddenly. Alpha blockers ('-osin') lower blood pressure and treat BPH; watch for orthostatic hypotension.", ["Beta blockers end in -olol", "Check pulse", "Don't stop suddenly", "Alpha blockers: orthostatic hypotension"]),
    ch(25, "Cholinergic Drugs", "Cholinergic drugs mimic the parasympathetic system: bethanechol (urinary retention) and drugs for myasthenia gravis (pyridostigmine). Side effects include salivation, sweating, and bradycardia. Atropine is the antidote.", ["Mimic parasympathetic", "Urinary retention", "Myasthenia gravis", "Atropine antidote"]),
    ch(26, "Cholinergic Blocking Drugs", "Anticholinergics (atropine, scopolamine, oxybutynin) reduce secretions and spasms. Side effects: dry mouth, constipation, urinary retention, blurred vision, and confusion in older adults ('dry as a bone, blind as a bat').", ["Dry mouth", "Urinary retention", "Blurred vision", "Confusion in older adults"]),
    ch(27, "Antiparkinson Drugs", "Parkinson's disease involves low dopamine. Carbidopa-levodopa is the main treatment; side effects include involuntary movements and orthostatic hypotension. Avoid high-protein meals with levodopa.", ["Carbidopa-levodopa", "Restore dopamine", "Involuntary movements", "Protein interferes"]),
    ch(28, "Antiepileptics", "Antiepileptics (phenytoin, levetiracetam, carbamazepine, valproic acid) prevent seizures. Don't stop abruptly—risk of status epilepticus. Phenytoin causes gingival hyperplasia; levels are monitored for some drugs.", ["Don't stop abruptly", "Phenytoin: gum overgrowth", "Monitor drug levels", "Seizure precautions"]),
    ch(29, "Skeletal Muscle, Bone, and Joint Disorder Drugs", "Drugs include muscle relaxants (cyclobenzaprine, baclofen), bisphosphonates for osteoporosis (alendronate—take with water on an empty stomach, stay upright 30 minutes), gout drugs (allopurinol, colchicine), and DMARDs for rheumatoid arthritis (methotrexate).", ["Bisphosphonates: upright 30 min", "Allopurinol for gout", "Muscle relaxants: drowsiness", "Methotrexate for RA"]),
    ch(30, "Upper Respiratory System Drugs", "Antihistamines (diphenhydramine causes drowsiness; loratadine less so), decongestants (pseudoephedrine; can raise BP; rebound congestion with nasal sprays), antitussives (dextromethorphan), and expectorants (guaifenesin; drink fluids).", ["Antihistamines: drowsiness", "Decongestants raise BP", "Rebound congestion", "Guaifenesin + fluids"]),
    ch(31, "Lower Respiratory System Drugs", "Bronchodilators include short-acting beta-agonists (albuterol, rescue), long-acting beta-agonists, and anticholinergics (ipratropium, tiotropium). Inhaled corticosteroids control inflammation (rinse mouth to prevent thrush). Leukotriene modifiers (montelukast) prevent asthma attacks.", ["Albuterol is rescue", "Inhaled steroids: rinse mouth", "Montelukast", "Use steroid inhaler daily"]),
    ch(32, "Diuretics", "Diuretics remove fluid: loop (furosemide; potassium loss), thiazides (hydrochlorothiazide; potassium loss), and potassium-sparing (spironolactone; risk of high potassium). Give in the morning, monitor weight, BP, and electrolytes.", ["Loop and thiazide lose K+", "Spironolactone keeps K+", "Give in the morning", "Daily weights"]),
    ch(33, "Antihyperlipidemic Drugs", "Statins ('-statin': atorvastatin) lower LDL cholesterol; watch for muscle pain (rhabdomyolysis) and liver problems; avoid grapefruit juice with some. Other drugs include bile acid sequestrants and ezetimibe.", ["Statins lower LDL", "Report muscle pain", "Liver tests", "Grapefruit interaction"]),
    ch(34, "Antihypertensive Drugs", "Antihypertensives include ACE inhibitors ('-pril'; dry cough, angioedema), ARBs ('-sartan'), calcium channel blockers, beta blockers, and diuretics. Teach patients to rise slowly to prevent orthostatic hypotension.", ["ACE inhibitors: cough", "ARBs end in -sartan", "Rise slowly", "Lifestyle changes too"]),
    ch(35, "Antianginal and Vasodilating Drugs", "Nitroglycerin relieves angina by dilating vessels: take sublingually every 5 minutes up to 3 doses; call 911 if pain persists after the first dose. Headache and hypotension are common. Avoid erectile dysfunction drugs with nitrates.", ["Sublingual nitro every 5 min ×3", "Headache common", "Hypotension", "No ED drugs"]),
    ch(36, "Anticoagulant and Thrombolytic Drugs", "Heparin (monitored by aPTT; antidote protamine sulfate) and warfarin (monitored by PT/INR; antidote vitamin K; keep vitamin K intake consistent) prevent clots. Direct oral anticoagulants (apixaban) need less monitoring. Thrombolytics dissolve clots. Watch for bleeding.", ["Heparin: aPTT, protamine", "Warfarin: INR, vitamin K", "Watch for bleeding", "Thrombolytics dissolve clots"]),
    ch(37, "Cardiotonic and Antiarrhythmic Drugs", "Digoxin strengthens heart contraction and slows rate; check apical pulse for 1 minute and hold if under 60; toxicity signs include nausea and visual changes (yellow halos), worse with low potassium. Antiarrhythmics (amiodarone) control abnormal rhythms.", ["Digoxin: check apical pulse", "Hold if < 60", "Toxicity: yellow halos", "Low K+ increases toxicity"]),
    ch(38, "Upper Gastrointestinal System Drugs", "Drugs include antacids, H2 blockers (famotidine), proton pump inhibitors ('-prazole'; take before breakfast), antiemetics (ondansetron), and treatments for H. pylori (antibiotics plus PPI).", ["PPIs end in -prazole", "Take PPI before breakfast", "Ondansetron for nausea", "H. pylori triple therapy"]),
    ch(39, "Lower Gastrointestinal System Drugs", "Laxatives (bulk-forming, stool softeners, stimulants, osmotic) treat constipation; antidiarrheals (loperamide) treat diarrhea. Bulk-forming laxatives need plenty of water. Other drugs treat IBD and IBS.", ["Bulk-forming: lots of water", "Stool softeners", "Loperamide", "IBD drugs"]),
    ch(40, "Antidiabetic Drugs", "Insulin types: rapid-acting (lispro), short-acting (regular—the only type given IV), intermediate (NPH; cloudy), and long-acting (glargine; no peak). Oral drugs include metformin (first-line; hold before contrast dye) and others. Hypoglycemia signs: shaking, sweating, confusion—treat with fast sugar.", ["Regular insulin given IV", "Glargine: no peak", "Metformin first-line", "Treat hypoglycemia with sugar"]),
    ch(41, "Pituitary and Adrenocortical Hormones", "Pituitary hormones include growth hormone and vasopressin (ADH). Corticosteroids (prednisone) reduce inflammation but cause high blood sugar, weight gain, infection risk, and bone loss; taper—don't stop suddenly.", ["Corticosteroids: taper", "High blood sugar", "Infection risk", "Vasopressin = ADH"]),
    ch(42, "Thyroid and Antithyroid Drugs", "Levothyroxine treats hypothyroidism; take on an empty stomach in the morning; too much causes hyperthyroid symptoms. Antithyroid drugs (methimazole, propylthiouracil) and radioactive iodine treat hyperthyroidism.", ["Levothyroxine on empty stomach", "Methimazole and PTU", "Radioactive iodine", "Monitor TSH"]),
    ch(43, "Male and Female Hormones", "Hormones include testosterone (androgens), estrogens, progestins, and hormonal contraceptives. Estrogen-containing drugs raise clot risk, especially in smokers.", ["Testosterone", "Estrogen and progestins", "Contraceptives", "Clot risk in smokers"]),
    ch(44, "Uterine Drugs", "Oxytocin stimulates labor contractions and controls postpartum bleeding; monitor contractions and fetal heart rate. Tocolytics slow preterm labor. Methylergonovine controls postpartum bleeding.", ["Oxytocin induces labor", "Monitor contractions", "Tocolytics stop labor", "Postpartum hemorrhage drugs"]),
    ch(45, "Menopause and Andropause Drugs", "Hormone therapy relieves menopause symptoms but has risks (clots, stroke, breast cancer) and is used at the lowest dose for the shortest time. Testosterone replacement treats low testosterone (andropause).", ["Lowest dose, shortest time", "Clot and cancer risk", "Testosterone replacement", "Symptom relief"]),
    ch(46, "Urinary Tract Anti-Infectives and Other Urinary Drugs", "Drugs include nitrofurantoin (UTIs; may darken urine), phenazopyridine (urinary pain relief; turns urine orange), and antispasmodics (oxybutynin) for overactive bladder. BPH drugs include tamsulosin and finasteride.", ["Nitrofurantoin for UTIs", "Phenazopyridine: orange urine", "Oxybutynin", "Tamsulosin for BPH"]),
    ch(47, "Vaccines", "Vaccines create active immunity; immune globulins give passive immunity. Live vaccines (MMR, varicella) are avoided in pregnancy and immunosuppression. Follow the immunization schedule and report adverse events (VAERS).", ["Active vs. passive immunity", "Live vaccines: avoid in pregnancy", "Immunization schedule", "VAERS"]),
    ch(48, "Immunostimulants and Modulators", "Immunostimulants include colony-stimulating factors (filgrastim—raises white cells; epoetin—raises red cells) and interferons, used in cancer and chronic diseases.", ["Filgrastim raises WBCs", "Epoetin raises RBCs", "Interferons", "Used in cancer care"]),
    ch(49, "Immune Blockers", "Immunosuppressants (cyclosporine, tacrolimus) prevent transplant rejection; biologics (TNF blockers) treat autoimmune disease. They increase infection risk—avoid crowds and sick contacts and live vaccines.", ["Prevent rejection", "Infection risk", "TNF blockers", "Avoid live vaccines"]),
    ch(50, "Traditional Chemotherapy", "Chemotherapy kills rapidly dividing cells, causing bone marrow suppression (infection, anemia, bleeding), nausea, hair loss, and mouth sores. Handle with special precautions (hazardous drugs).", ["Bone marrow suppression", "Nausea and hair loss", "Neutropenic precautions", "Hazardous drug handling"]),
    ch(51, "Immune Modulating Therapies", "Targeted therapies and immunotherapies (monoclonal antibodies, 'mab' drugs; checkpoint inhibitors) attack specific cancer features or boost immune response, with immune-related side effects.", ["Monoclonal antibodies (-mab)", "Targeted therapy", "Checkpoint inhibitors", "Immune-related effects"]),
    ch(52, "Skin Disorder Topical Drugs", "Topical drugs include antibiotics (mupirocin), antifungals, corticosteroids (use thin layers, short-term), antiseptics, and drugs for acne and psoriasis. Isotretinoin causes birth defects and requires pregnancy prevention.", ["Topical steroids: thin layer", "Mupirocin", "Isotretinoin: birth defects", "Antiseptics"]),
    ch(53, "Otic and Ophthalmic Preparations", "Eye drops for glaucoma (timolol, latanoprost) lower eye pressure; apply pressure to the inner corner of the eye after drops. For adult ear drops, pull the ear up and back; for children under 3, down and back.", ["Glaucoma drops", "Punctal pressure", "Adult ear: up and back", "Child ear: down and back"]),
    ch(54, "Fluids, Electrolytes, and Parenteral Therapy", "IV fluids are isotonic (normal saline, lactated Ringer's), hypotonic, or hypertonic. Potassium must never be given IV push. Electrolyte imbalances include hypo/hyperkalemia and hyponatremia. Total parenteral nutrition provides nutrients IV.", ["Isotonic fluids", "Never IV push potassium", "Electrolyte imbalances", "TPN"]),
]

